CREATE DATABASE IF NOT EXISTS se_conecte CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE se_conecte;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,senha_hash VARCHAR(255) NOT NULL,xp INT DEFAULT 0,nivel VARCHAR(40) DEFAULT 'Iniciante',criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE preferencias_acessibilidade(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNIQUE NOT NULL,tamanho_texto ENUM('normal','large','extra') DEFAULT 'normal',alto_contraste BOOLEAN DEFAULT 0,reduzir_animacoes BOOLEAN DEFAULT 0,modo_aprender_mais BOOLEAN DEFAULT 0,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE cursos(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(80) UNIQUE NOT NULL,titulo VARCHAR(160) NOT NULL,categoria VARCHAR(80) NOT NULL,descricao TEXT,duracao_minutos INT DEFAULT 0,xp INT DEFAULT 0,ativo BOOLEAN DEFAULT 1);
CREATE TABLE aulas(id INT AUTO_INCREMENT PRIMARY KEY,curso_id INT NOT NULL,titulo VARCHAR(160) NOT NULL,conteudo LONGTEXT,conteudo_simplificado LONGTEXT,video_url VARCHAR(255),ordem INT NOT NULL,FOREIGN KEY(curso_id) REFERENCES cursos(id) ON DELETE CASCADE);
CREATE TABLE progresso(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,curso_id INT NOT NULL,percentual TINYINT UNSIGNED DEFAULT 0,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_prog(usuario_id,curso_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(curso_id) REFERENCES cursos(id) ON DELETE CASCADE);
CREATE TABLE competencias(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE usuario_competencias(usuario_id INT NOT NULL,competencia_id INT NOT NULL,nivel TINYINT UNSIGNED DEFAULT 1,PRIMARY KEY(usuario_id,competencia_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(competencia_id) REFERENCES competencias(id) ON DELETE CASCADE);
CREATE TABLE vagas(id INT AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(160) NOT NULL,empresa VARCHAR(160) NOT NULL,modalidade VARCHAR(60),cidade VARCHAR(100),descricao TEXT,ativa BOOLEAN DEFAULT 1);
CREATE TABLE vaga_competencias(vaga_id INT NOT NULL,competencia_id INT NOT NULL,peso TINYINT UNSIGNED DEFAULT 1,PRIMARY KEY(vaga_id,competencia_id),FOREIGN KEY(vaga_id) REFERENCES vagas(id) ON DELETE CASCADE,FOREIGN KEY(competencia_id) REFERENCES competencias(id) ON DELETE CASCADE);
